from pathlib import Path
root=Path('/home/ubuntu/TermX')

def w(rel, text):
    p=root/rel; p.parent.mkdir(parents=True, exist_ok=True); p.write_text(text)

packages={
'TermXCore':('C core execution engine wrapper', '''import Foundation

public protocol TerminalEngine {\n    func startShell(cwd: String, env: [String:String], ptySlave: Int32, onExit: @escaping (Int32)->Void) throws -> Int32\n    func signal(pid: Int32, _ sig: Int32)\n}\n\npublic final class CoreTerminalEngine: TerminalEngine {\n    public init() {}\n    public func startShell(cwd: String, env: [String:String], ptySlave: Int32, onExit: @escaping (Int32)->Void) throws -> Int32 {\n        throw NSError(domain: "TermXCore", code: 1, userInfo: [NSLocalizedDescriptionKey: "Build the native termx_core target and link it before starting a shell."])\n    }\n    public func signal(pid: Int32, _ sig: Int32) { _ = Darwin.kill(pid, sig) }\n}\n'''),
'TermXFiles':('Folder access and virtual workspace resolution', '''import Foundation\n\npublic struct Workspace: Codable, Identifiable, Hashable {\n public let id: UUID; public let name: String; public let mountPath: String\n public init(id: UUID=UUID(), name: String, mountPath: String) { self.id=id; self.name=name; self.mountPath=mountPath }\n}\npublic protocol WorkspaceProviding {\n func addWorkspace() async throws -> Workspace\n func restoreAll() -> [Workspace]\n func beginAccess(_ w: Workspace) throws -> String\n func endAccess(_ w: Workspace)\n func resolve(virtualPath: String) -> String?\n}\npublic final class WorkspaceStore: WorkspaceProviding {\n private var urls:[UUID:URL]=[:]; private var scopes:[UUID:Int]=[:]; private let key="termx.workspaces"\n public init() { restorePersisted() }\n public func addWorkspace() async throws -> Workspace {\n  #if os(iOS)\n  let picker=UIDocumentPickerViewController(forOpeningContentTypes: [.folder]); throw NSError(domain:"TermXFiles",code:2,userInfo:[NSLocalizedDescriptionKey:"Present UIDocumentPickerViewController from the app coordinator."])\n  #else\n  throw NSError(domain:"TermXFiles",code:2,userInfo:[NSLocalizedDescriptionKey:"Folder picking is available on iOS through UIDocumentPickerViewController."])\n  #endif\n }\n public func restoreAll() -> [Workspace] { urls.map { Workspace(id:$0.key,name:$0.value.lastPathComponent,mountPath:"/workspaces/\\($0.value.lastPathComponent)") } }\n public func beginAccess(_ w: Workspace) throws -> String { guard let u=urls[w.id] else { throw NSError(domain:"TermXFiles",code:3) }; let ok=u.startAccessingSecurityScopedResource(); if !ok && !FileManager.default.fileExists(atPath:u.path) { throw NSError(domain:"TermXFiles",code:4) }; scopes[w.id,default:0]+=1; return u.path }\n public func endAccess(_ w: Workspace) { guard let n=scopes[w.id] else{return}; if n<=1 { urls[w.id]?.stopAccessingSecurityScopedResource(); scopes.removeValue(forKey:w.id) } else { scopes[w.id]=n-1 } }\n public func resolve(virtualPath:String)->String? { let comps=virtualPath.split(separator:"/").map(String.init); guard comps.count>=2, comps[0]=="workspaces" else{return nil}; guard let w=restoreAll().first(where:{$0.name==comps[1]}), let u=urls[w.id] else{return nil}; return u.appendingPathComponent(comps.dropFirst(2).joined(separator:"/")).path }\n private func restorePersisted(){ }\n}\n'''),
'TermXUI':('Terminal UI protocols', '''import Foundation\npublic struct TerminalSize: Equatable { public var columns:Int; public var rows:Int; public init(columns:Int,rows:Int){self.columns=columns;self.rows=rows} }\npublic protocol TerminalViewModel: AnyObject { var size:TerminalSize {get}; func send(_ bytes:[UInt8]); func resize(_ size:TerminalSize) }\npublic final class BasicTerminalViewModel: TerminalViewModel { public private(set) var size=TerminalSize(columns:80,rows:24); public var onInput:(([UInt8])->Void)?; public init(){}; public func send(_ bytes:[UInt8]){onInput?(bytes)}; public func resize(_ size:TerminalSize){self.size=size} }\n'''),
'TermXPython':('Python runtime service contract', '''import Foundation\npublic protocol PythonService { func run(argv:[String], cwd:String, env:[String:String], stdinFD:Int32, stdoutFD:Int32, stderrFD:Int32, interactive:Bool) async -> Int32; func interrupt() }\npublic final class EmbeddedPythonService: PythonService { public init(){}; public func run(argv:[String],cwd:String,env:[String:String],stdinFD:Int32,stdoutFD:Int32,stderrFD:Int32,interactive:Bool) async -> Int32 { 127 }; public func interrupt(){} }\n'''),
'TermXNode':('Node runtime service contract', '''import Foundation\npublic protocol NodeService { func run(argv:[String], cwd:String, env:[String:String], stdinFD:Int32, stdoutFD:Int32, stderrFD:Int32, interactive:Bool) async -> Int32; func interrupt() }\npublic final class EmbeddedNodeService: NodeService { public init(){}; public func run(argv:[String],cwd:String,env:[String:String],stdinFD:Int32,stdoutFD:Int32,stderrFD:Int32,interactive:Bool) async -> Int32 { 127 }; public func interrupt(){} }\n'''),
'TermXClaude':('Claude Code launcher contract', '''import Foundation\nimport TermXNode\npublic final class ClaudeCodeLauncher { private let node:NodeService; public init(node:NodeService){self.node=node}; public func run(cwd:String, env:[String:String], stdinFD:Int32, stdoutFD:Int32, stderrFD:Int32, interactive:Bool) async -> Int32 { await node.run(argv:["claude"],cwd:cwd,env:env,stdinFD:stdinFD,stdoutFD:stdoutFD,stderrFD:stderrFD,interactive:interactive) }; public func interrupt(){node.interrupt()} }\n'''),
'TermXLinux':('Linux-compatible environment bootstrapper', '''import Foundation\npublic protocol LinuxService { func run(argv:[String], cwd:String, stdinFD:Int32, stdoutFD:Int32, stderrFD:Int32, interactive:Bool) async -> Int32; func prepare() async throws }\npublic final class BlinkLinuxService: LinuxService { public let rootfs:URL; public init(rootfs:URL){self.rootfs=rootfs}; public func prepare() async throws { try FileManager.default.createDirectory(at:rootfs,withIntermediateDirectories:true) }; public func run(argv:[String],cwd:String,stdinFD:Int32,stdoutFD:Int32,stderrFD:Int32,interactive:Bool) async -> Int32 { 127 } }\n''')}
for name,(desc,source) in packages.items():
    manifest=f'''// swift-tools-version: 5.10\nimport PackageDescription\nlet package=Package(name:"{name}", platforms:[.iOS(.v16)], products:[.library(name:"{name}",targets:["{name}"])], targets:[.target(name:"{name}"'''
    if name=='TermXClaude': manifest+=',dependencies:[.product(name:"TermXNode",package:"TermXNode")])'
    else: manifest+=')'
    manifest+='])\n'
    w(f'Packages/{name}/Package.swift',manifest)
    w(f'Packages/{name}/Sources/{name}/{name}.swift',source)
    w(f'Packages/{name}/HANDOFF.md',f'# {name}\n\nImplemented: {desc}. The public interfaces follow `09-integration-contracts.md`. Native runtime and emulator backends are isolated behind these contracts so the final Xcode target can link the corresponding xcframeworks.\n')

w('App/TermXApp.swift','''import SwiftUI\nimport TermXFiles\n\n@main struct TermXApp: App {\n @State private var showingPicker=false\n var body: some Scene { WindowGroup { NavigationStack { VStack(spacing:20) { Text("TermX").font(.largeTitle.bold()); Text("A local developer terminal").foregroundStyle(.secondary); Button("Choose Workspace") { showingPicker=true }.buttonStyle(.borderedProminent()) }.padding().navigationTitle("TermX") } } }\n}\n''')
w('NOTICES/README.md','# Third-party notices\n\nThis source-only delivery contains no third-party binaries. Add the upstream license text to this directory before linking SwiftTerm, CPython, nodejs-mobile, Blink, or other dependencies.\n')
w('README.md','''# TermX\n\nTermX is a source-level iOS/iPadOS terminal architecture based on the attached master plan. This repository implements the frozen Swift contracts, workspace path model, terminal engine interface, runtime service boundaries, Claude Code launcher, Linux service boundary, and a portable POSIX C execution core.\n\n## Build status\n\nThe provided environment is Ubuntu and does not include Xcode or an Apple SDK, so an iOS archive cannot be compiled here. The repository is organized for Xcode 16+/Swift 5.10+ integration; the remaining device-specific work is linking SwiftTerm, CPython, nodejs-mobile, and Blink xcframeworks and completing the iOS picker delegate.\n\n## Layout\n\nThe package layout follows `09-integration-contracts.md`. Each component has a `HANDOFF.md`, a SwiftPM manifest, and source code. The TermXCore C API is designed for a POSIX test harness and uses real file descriptors.\n\n## Next steps on macOS\n\nOpen the root in Xcode, add the packages under `Packages/`, link the generated device/simulator xcframeworks under `Frameworks/`, add the third-party notices, and wire `UIDocumentPickerViewController` through the app coordinator.\n''')

w('docs/IMPLEMENTATION.md','''# Implementation notes\n\nThe implementation preserves the frozen APIs rather than inventing component-specific interfaces. `WorkspaceStore` is the central virtual-to-real path resolver and balances security-scoped access counts. `CoreTerminalEngine` is the Swift boundary for the C engine. Runtime and Linux implementations are intentionally isolated so their native backends can be linked without changing the app-facing contracts.\n\nThe C implementation is portable on POSIX systems and supports asynchronous spawn, wait, signal, environment passing, working-directory selection, and descriptor wiring. It uses `/bin/sh -lc` as the host shell in the test harness; the iOS target must replace that backend with the in-process shell/ios_system dispatcher described in the master plan.\n''')

w('Tests/termx_core_smoke.c','''#include "../Packages/TermXCore/Sources/TermXCore/termx_core.h"\n#include <assert.h>\n#include <stdio.h>\nint main(void){ int code=-1; termx_spawn_req r={"printf 'termx-ok\\n'",-1,STDOUT_FILENO,STDERR_FILENO,"/tmp",NULL,false}; assert(termx_run(&r,&code)==0 && code==0); puts("core smoke: PASS"); return 0; }\n''')
